{
  "items": [
    {
      "name": "Finset.prod_le_pow_card",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : CommMonoid N] [inst_1 : PartialOrder N] [MulLeftMono N] (s : Finset ι)\n  (f : ι → N) (n : N), (∀ x ∈ s, f x ≤ n) → s.prod f ≤ n ^ s.card"
    },
    {
      "name": "Finset.prod_le_one",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_2} [inst : CommMonoidWithZero R] [inst_1 : PartialOrder R] [ZeroLEOneClass R]\n  [PosMulMono R] {f : ι → R} {s : Finset ι}, (∀ i ∈ s, 0 ≤ f i) → (∀ i ∈ s, f i ≤ 1) → ∏ i ∈ s, f i ≤ 1"
    },
    {
      "name": "enorm_prod_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {ε : Type u_8} [inst : TopologicalSpace ε] [inst_1 : ESeminormedCommMonoid ε] (s : Finset ι)\n  {f : ι → ε} {n : ι → ENNReal}, (∀ b ∈ s, ‖f b‖ₑ ≤ n b) → ‖∏ b ∈ s, f b‖ₑ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "Real.finset_prod_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (s : Finset ι) (f : ι → ℝ), (∀ i ∈ s, 0 ≤ f i) → ∀ (r : ℝ), ∏ i ∈ s, f i ^ r = (∏ i ∈ s, f i) ^ r"
    },
    {
      "name": "NNReal.finset_prod_rpow",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (s : Finset ι) (f : ι → NNReal) (r : ℝ), ∏ i ∈ s, f i ^ r = (∏ i ∈ s, f i) ^ r"
    }
  ]
}
